package forth

import (
	"errors"
	"fmt"
	"strconv"
	"strings"
)

// forth is a minimal evaluator for a small subset of Forth.
type forth struct {
	stack []int
	words map[string]func(*forth) error
}

func newForth() *forth {
	f := &forth{
		stack: []int{},
		words: map[string]func(*forth) error{},
	}
	f.words["+"] = f.binary(func(a, b int) (int, error) {
		return a + b, nil
	})
	f.words["-"] = f.binary(func(a, b int) (int, error) {
		return a - b, nil
	})
	f.words["*"] = f.binary(func(a, b int) (int, error) {
		return a * b, nil
	})
	f.words["/"] = f.binary(func(a, b int) (int, error) {
		if b == 0 {
			return 0, errors.New("division by zero")
		}
		return a / b, nil
	})
	f.words["dup"] = func(f *forth) error {
		if len(f.stack) < 1 {
			return errors.New("empty stack")
		}
		return f.push(f.stack[len(f.stack)-1])
	}
	f.words["drop"] = func(f *forth) error {
		if len(f.stack) < 1 {
			return errors.New("empty stack")
		}
		_, err := f.pop()
		return err
	}
	f.words["swap"] = func(f *forth) error {
		if len(f.stack) < 2 {
			return errors.New("stack underflow")
		}
		n := len(f.stack)
		f.stack[n-1], f.stack[n-2] = f.stack[n-2], f.stack[n-1]
		return nil
	}
	f.words["over"] = func(f *forth) error {
		if len(f.stack) < 2 {
			return errors.New("stack underflow")
		}
		return f.push(f.stack[len(f.stack)-2])
	}
	return f
}

func (f *forth) push(v int) error {
	f.stack = append(f.stack, v)
	return nil
}

func (f *forth) pop() (int, error) {
	if len(f.stack) < 1 {
		return 0, errors.New("empty stack")
	}
	v := f.stack[len(f.stack)-1]
	f.stack = f.stack[:len(f.stack)-1]
	return v, nil
}

// binary pops two values (a is second from the top, b is the top),
// applies op to them and pushes the result.
func (f *forth) binary(op func(a, b int) (int, error)) func(*forth) error {
	return func(f *forth) error {
		b, err := f.pop()
		if err != nil {
			return err
		}
		a, err := f.pop()
		if err != nil {
			return err
		}
		v, err := op(a, b)
		if err != nil {
			return err
		}
		return f.push(v)
	}
}

// isNumber reports whether token is a (possibly negative) integer literal.
func isNumber(token string) bool {
	_, err := strconv.Atoi(token)
	return err == nil
}

// resolve turns a token into the operation it represents, resolving
// user-defined words against the current dictionary.
func (f *forth) resolve(token string) (func(*forth) error, error) {
	if v, err := strconv.Atoi(token); err == nil {
		return func(f *forth) error { return f.push(v) }, nil
	}
	name := strings.ToLower(token)
	if op, ok := f.words[name]; ok {
		return op, nil
	}
	return nil, fmt.Errorf("undefined operation %q", name)
}

// exec executes a single token.
func (f *forth) exec(token string) error {
	if v, err := strconv.Atoi(token); err == nil {
		return f.push(v)
	}
	name := strings.ToLower(token)
	if op, ok := f.words[name]; ok {
		return op(f)
	}
	return fmt.Errorf("undefined operation %q", name)
}

// define registers a new word from tokens of the form
// [":", name, body..., ";"]. The body is resolved against the
// dictionary as it exists at definition time, so later
// redefinitions of words used in the body do not affect the new word.
func (f *forth) define(tokens []string) error {
	if len(tokens) < 3 || strings.ToLower(tokens[len(tokens)-1]) != ";" {
		return errors.New("incomplete word definition")
	}
	name := strings.ToLower(tokens[1])
	if isNumber(tokens[1]) {
		return fmt.Errorf("cannot define a number: %q", tokens[1])
	}
	body := tokens[2 : len(tokens)-1]
	ops := make([]func(*forth) error, 0, len(body))
	for _, t := range body {
		op, err := f.resolve(t)
		if err != nil {
			return err
		}
		ops = append(ops, op)
	}
	f.words[name] = func(f *forth) error {
		for _, op := range ops {
			if err := op(f); err != nil {
				return err
			}
		}
		return nil
	}
	return nil
}

// Forth evaluates a sequence of Forth lines and returns the final stack.
func Forth(input []string) ([]int, error) {
	f := newForth()
	for _, line := range input {
		tokens := strings.Fields(line)
		for i := 0; i < len(tokens); i++ {
			if strings.ToLower(tokens[i]) == ":" {
				j := i + 1
				for j < len(tokens) && strings.ToLower(tokens[j]) != ";" {
					j++
				}
				if j >= len(tokens) {
					return nil, errors.New("incomplete word definition")
				}
				if err := f.define(tokens[i : j+1]); err != nil {
					return nil, err
				}
				i = j
			} else if err := f.exec(tokens[i]); err != nil {
				return nil, err
			}
		}
	}
	return f.stack, nil
}

